SELECT no_plan();
CREATE TEMP TABLE square_renewal_fixture(booking_id uuid,period_id uuid,guest_user uuid,admin_user uuid,other_user uuid,attempt jsonb,original_booking jsonb);
GRANT ALL ON square_renewal_fixture TO authenticated,service_role;
DO $$ DECLARE b public.bookings%ROWTYPE; actor uuid; guest uuid; other uuid; planned jsonb; period uuid; BEGIN
 SELECT * INTO b FROM public.bookings WHERE reservation_number='ZNX-000150';
 SELECT user_id INTO actor FROM public.profiles WHERE is_admin LIMIT 1;
 SELECT user_id INTO guest FROM public.profiles WHERE id=b.renter_profile_id;
 SELECT user_id INTO other FROM public.profiles WHERE id<>b.renter_profile_id AND NOT is_admin LIMIT 1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',actor,'role','authenticated')::text,true);
 planned:=public.admin_schedule_rental_extension(b.id,b.end_date+30,b.dropoff_time,158400,true,'Synthetic Square renewal test');
 PERFORM public.admin_activate_rental_extension((planned->>'plan_id')::uuid);
 SELECT id INTO period FROM public.rental_extension_periods WHERE extension_plan_id=(planned->>'plan_id')::uuid ORDER BY period_number LIMIT 1;
 INSERT INTO square_renewal_fixture SELECT b.id,period,guest,actor,other,NULL,to_jsonb(x) FROM public.bookings x WHERE x.id=b.id;
END $$;
ALTER TABLE square_renewal_fixture ADD COLUMN link text;
SET LOCAL ROLE service_role;
UPDATE square_renewal_fixture SET link=ensure_square_renewal_link(period_id);
SELECT is((SELECT length(link)::integer FROM square_renewal_fixture),64,'Public URL uses a 256-bit capability');
SELECT is((SELECT ensure_square_renewal_link(period_id) FROM square_renewal_fixture),(SELECT link FROM square_renewal_fixture),'Email and copied URL reuse the same link');
SELECT set_config('request.jwt.claims','{}',true);
SELECT is((SELECT get_public_square_renewal_details(link)->>'can_pay' FROM square_renewal_fixture),'true','Public link is payable with no login');
SELECT is((SELECT get_public_square_renewal_details(link)->>'amount_cents' FROM square_renewal_fixture),'158400','Public link has fixed server amount');
SELECT is((SELECT count(*)::integer FROM square_renewal_payment_attempts),0,'Opening public link creates no attempt');
UPDATE square_renewal_fixture SET attempt=prepare_public_square_renewal_payment(link,'live','location');
SELECT is((SELECT attempt->>'dispatch' FROM square_renewal_fixture),'true','Public card submission can dispatch exactly once');
SELECT is((SELECT prepare_public_square_renewal_payment(link,'live','location')->>'dispatch' FROM square_renewal_fixture),'false','Concurrent public submission cannot create duplicate charge');
SELECT ok((SELECT created_by_profile_id IS NULL FROM square_renewal_payment_attempts WHERE id=(SELECT (attempt->>'id')::uuid FROM square_renewal_fixture)),'Public payer is not falsely attributed to guest or admin');
SELECT record_square_renewal_payment((attempt->>'id')::uuid,'square-public-id',158400,'location','live','COMPLETED') FROM square_renewal_fixture;
SELECT is((SELECT get_public_square_renewal_details(link)->>'can_pay' FROM square_renewal_fixture),'false','Paid public URL no longer accepts payment');
SELECT is((SELECT prepare_public_square_renewal_payment(link,'live','location')->>'already_paid' FROM square_renewal_fixture),'true','Paid URL never starts another payment');
SELECT is((SELECT payment_status FROM rental_extension_periods WHERE id=(SELECT period_id FROM square_renewal_fixture)),'paid','Canonical Square evidence updates associated renewal');
SELECT is((SELECT count(*)::integer FROM rental_extension_events WHERE period_id=(SELECT period_id FROM square_renewal_fixture) AND event_type='payment_succeeded'),1,'Public payment has one audit event');
SELECT is((SELECT to_jsonb(b) FROM bookings b WHERE id=(SELECT booking_id FROM square_renewal_fixture)),(SELECT original_booking FROM square_renewal_fixture),'Original booking and deposit fields unchanged');
SELECT is((SELECT count(*)::integer FROM booking_security_deposits),0,'Public renewal creates no HOLD');
RESET ROLE;
SET LOCAL ROLE anon;
SELECT throws_like('SELECT get_public_square_renewal_details(link) FROM square_renewal_fixture','%permission denied%','Anonymous browsers cannot call privileged database settlement helpers');
RESET ROLE;
